import subprocess
from pathlib import Path


def test_selected_real_submission_feedback_and_managed_retry_guards():
    script=r'''
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),ts=require('./ui/node_modules/typescript');
const hooks=[];let index=0,effects=[],tree;const same=(a,b)=>a&&b&&a.length===b.length&&a.every((v,i)=>v===b[i]);
const react={useState(v){const i=index++;if(!hooks[i])hooks[i]={v:typeof v==='function'?v():v};return[hooks[i].v,n=>{hooks[i].v=typeof n==='function'?n(hooks[i].v):n}]},useMemo(fn,deps){const i=index++;if(!hooks[i]||!same(hooks[i].deps,deps))hooks[i]={v:fn(),deps};return hooks[i].v},useCallback(fn,deps){return react.useMemo(()=>fn,deps)},useRef(v){return react.useMemo(()=>({current:v}),[])},useEffect(fn,deps){const i=index++;if(!hooks[i]||!same(hooks[i].deps,deps)){hooks[i]?.cleanup?.();hooks[i]={deps};effects.push(()=>{hooks[i].cleanup=fn()})}}};
const calls=[];const item={submission_id:'native-test',company:'合成公司',position:'岗位',channel:'liepin',mode:'submit',status:'success',error:'',job_url:'',submitted_at:'',last_step:{name:'receipt',status:'success',detail:''},rate_limit_detail:'',retry_allowed:false};
const binding={status:'verified',parent_run_id:'approved',job_lead_id:'lead',resume_version_id:'version',resume_sha256:'a'.repeat(64),receipt_sha256:'b'.repeat(64),receipt_source:'app_browser',delivery_kind:'generated_pdf'};
const old={iteration_id:'old',user_notes:'之前记录',feedback_source:'user_note',selected_actions:['acknowledge_and_skip'],created_at:'2026-10-01',next_recommended_step:'review_iteration_record'};
const list={source_run_id:item.submission_id,source_binding:binding,items:[{source_type:'submission_receipt'}],iterations:[old],supported_actions:['acknowledge_and_skip','add_or_edit_evidence_card']};
const api={listSubmissions:async()=>({items:[item]}),getChannelSession:async()=>({artifact_paths:{},session:{login_status:'session_unknown',account_identity:{}}}),listSubmissionFeedback:async id=>{calls.push(['list',id]);return list},getSubmissionDetail:async()=>({submission:{...item,...binding,evidence:binding,steps:[],started_at:'',ended_at:'',resume_version_id:'version'}}),createFeedbackIteration:async payload=>{calls.push(['save',payload]);return{iteration:{...old,iteration_id:'new',user_notes:payload.user_notes,selected_actions:payload.selected_actions},iteration_id:'new',record_path:'saved'}},retrySubmission:async()=>{throw Error('禁止重试')}};
const exports={},jsx=(type,props)=>({type,props:props||{}});vm.runInNewContext(ts.transpileModule(fs.readFileSync('ui/src/pages/submissions/index.tsx','utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2021,jsx:ts.JsxEmit.ReactJSX}}).outputText,{exports,console,Intl,Date,Map,Set,encodeURIComponent,require:n=>{if(n==='react-router-dom')return{useSearchParams:()=>[{get:()=>null}],useNavigate:()=>()=>{}};if(n==='react')return react;if(n==='react/jsx-runtime')return{jsx,jsxs:jsx};if(n==='react-i18next')return{useTranslation:()=>({t:k=>k,i18n:{language:'zh'}})};if(n==='@tauri-apps/api/core')return{convertFileSrc:x=>x};if(n==='lucide-react')return new Proxy({},{get:(_,k)=>k});if(n==='@/lib/errors')return{getErrorMessage:e=>String(e)};if(n==='@/lib/sidecar/api')return api;throw Error(n)}});
const nodes=v=>Array.isArray(v)?v.flatMap(nodes):v&&typeof v==='object'?[v,...nodes(v.props.children)]:[];const text=v=>Array.isArray(v)?v.map(text).join(' '):v&&typeof v==='object'?text(v.props.children):String(v??'');
async function settle(){for(let i=0;i<8;i++){index=0;tree=exports.SubmissionsPage();const pending=effects;effects=[];for(const fn of pending)fn();await Promise.resolve();await Promise.resolve()}}
const button=k=>nodes(tree).find(n=>n.type==='button'&&text(n).trim()===k);const field=k=>nodes(tree).find(n=>n.props['aria-label']===k);
(async()=>{await settle();const selector=field('pages.submissions.feedback.submission');assert.ok(selector,'必须可选择历史真实投递');selector.props.onChange({target:{value:'native-test'}});await settle();assert.ok(calls.some(c=>c[0]==='list'&&c[1]==='native-test'));assert.ok(text(tree).includes('之前记录'));
assert.ok(button('pages.submissions.feedback.create').props.disabled,'空反馈不能落盘');field('pages.submissions.feedback.notes').props.onChange({target:{value:'个人复盘：验证闭环，没有招聘方回复。'}});await settle();assert.equal(button('pages.submissions.feedback.create').props.disabled,false);await button('pages.submissions.feedback.create').props.onClick();await settle();const sent=calls.find(c=>c[0]==='save')[1];assert.equal(sent.source_run_id,'native-test');assert.equal(sent.feedback_source,'user_note');assert.equal(JSON.stringify(sent.selected_actions),JSON.stringify(['acknowledge_and_skip']));assert.ok(sent.user_notes.includes('没有招聘方回复'));
for(const key of ['sameChannel','fallbackEmail'])assert.ok(nodes(tree).find(n=>n.type==='button'&&text(n).includes('pages.submissions.retryStrategy.'+key)).props.disabled,'详情页也必须禁止重复投递');assert.ok(text(tree).includes(binding.receipt_sha256));
})().catch(e=>{console.error(e);process.exitCode=1});
'''
    result=subprocess.run(['node','-e',script],cwd=Path(__file__).resolve().parents[3],capture_output=True,text=True,timeout=30)
    assert result.returncode==0,result.stdout+result.stderr
